"""Convert an inline-XBRL 10-K HTML document to paragraph-structured plain text.
Usage: python3 -I html2text.py in.htm out.txt
"""
import sys, re, html
from html.parser import HTMLParser

SKIP = {"script", "style", "ix:header", "head", "title"}
BLOCK = {"p", "div", "h1", "h2", "h3", "h4", "h5", "h6", "li", "ul", "ol",
         "table", "section", "article", "blockquote", "hr", "body", "html"}
VOID = {"br", "hr", "img", "meta", "link", "input"}


class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out = []          # list of blocks (strings)
        self.cur = []          # current inline text pieces
        self.skip = 0
        self.stack = []        # (tag, hidden_flag)
        self.row = None        # list of cells when inside tr
        self.cell = None

    def flush(self):
        t = "".join(self.cur)
        t = re.sub(r"[ \t\r\f\v ​]+", " ", t).strip()
        self.cur = []
        if t:
            if self.cell is not None:
                self.cell.append(t)
            else:
                self.out.append(t)

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        hidden = tag in SKIP or "display:none" in (a.get("style") or "").replace(" ", "").lower()
        if tag not in VOID:
            self.stack.append((tag, hidden))
            if hidden:
                self.skip += 1
        if self.skip:
            return
        if tag == "br":
            self.cur.append(" ")
        elif tag == "tr":
            self.flush(); self.row = []
        elif tag in ("td", "th"):
            self.flush(); self.cell = []
        elif tag in BLOCK:
            self.flush()

    def handle_endtag(self, tag):
        if tag in VOID:
            return
        # pop to matching tag
        idx = None
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] == tag:
                idx = i; break
        if idx is None:
            return
        was_skipping = self.skip > 0
        for t, h in self.stack[idx:]:
            if h:
                self.skip -= 1
        del self.stack[idx:]
        if was_skipping and self.skip:
            return
        if was_skipping and not self.skip:
            self.cur = []
            return
        if tag in ("td", "th"):
            self.flush()
            if self.cell is not None and self.row is not None:
                c = " ".join(self.cell).strip()
                if c:
                    self.row.append(c)
            self.cell = None
        elif tag == "tr":
            self.flush()
            if self.row:
                line = " | ".join(self.row)
                # merge stray "$" / ")" / "%" cells
                line = re.sub(r"\$ \| ", "$", line)
                line = re.sub(r" \| (\)|%)", r"\1", line)
                self.out.append(("ROW", line))
            self.row = None
        elif tag in BLOCK:
            self.flush()
            if tag == "table":
                self.out.append(("ENDTABLE", ""))

    def handle_data(self, data):
        if not self.skip:
            self.cur.append(data)


def convert(src):
    p = P()
    p.feed(src)
    p.close()
    p.flush()
    paras, table = [], []
    for b in p.out:
        if isinstance(b, tuple):
            if b[0] == "ROW":
                table.append(b[1])
            else:
                if table:
                    paras.append("\n".join(table)); table = []
        else:
            if table:
                paras.append("\n".join(table)); table = []
            paras.append(b)
    if table:
        paras.append("\n".join(table))
    # drop page-number-only and table-of-contents noise lines
    cleaned = []
    for x in paras:
        s = x.strip()
        if not s or re.fullmatch(r"\d{1,3}", s) or s.lower() == "table of contents":
            continue
        cleaned.append(s)
    return "\n\n".join(cleaned) + "\n"


if __name__ == "__main__":
    src = open(sys.argv[1], encoding="utf-8", errors="replace").read()
    open(sys.argv[2], "w", encoding="utf-8").write(convert(src))

